export interface Profile {
  id: string;
  name: string;
  badge: number[] | null;
}

export class ProfileError extends Error {
  constructor(public readonly code: 'DUPLICATE' | 'MISSING' | 'INVALID_NAME' | 'INVALID_BADGE') {
    super(code);
    this.name = 'ProfileError';
  }
}

function clone(profile: Profile): Profile {
  return {
    id: profile.id,
    name: profile.name,
    badge: profile.badge === null ? null : [...profile.badge],
  };
}

function validateBadge(badge: readonly number[] | null): void {
  if (badge !== null && badge.some(value => !Number.isInteger(value) || value < 0 || value > 255)) {
    throw new ProfileError('INVALID_BADGE');
  }
}

export class ProfileRegistry {
  private readonly profiles: Profile[];

  constructor(initial: readonly Profile[] = []) {
    const seen = new Set<string>();
    this.profiles = initial.map(profile => {
      if (seen.has(profile.id)) throw new ProfileError('DUPLICATE');
      if (typeof profile.name !== 'string' || profile.name.trim() === '') {
        throw new ProfileError('INVALID_NAME');
      }
      validateBadge(profile.badge);
      seen.add(profile.id);
      return clone(profile);
    });
  }

  private index(id: string): number {
    const index = this.profiles.findIndex(profile => profile.id === id);
    if (index < 0) throw new ProfileError('MISSING');
    return index;
  }

  get(id: string): Profile {
    return clone(this.profiles[this.index(id)]);
  }

  list(): Profile[] {
    return this.profiles.map(clone);
  }

  rename(id: string, name: string): Profile {
    const index = this.index(id);
    const trimmed = name.trim();
    if (!trimmed) throw new ProfileError('INVALID_NAME');
    this.profiles[index].name = trimmed;
    return clone(this.profiles[index]);
  }

  setBadge(id: string, bytes: readonly number[]): Profile {
    const index = this.index(id);
    validateBadge(bytes);
    this.profiles[index].badge = bytes as number[];
    return clone(this.profiles[index]);
  }

  clearBadge(id: string): Profile {
    const index = this.index(id);
    this.profiles[index].badge = null;
    return clone(this.profiles[index]);
  }
}

