import { ProfileRegistry, ProfileError } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectCode(code: string, action: () => unknown): void {
  try { action(); } catch (error) {
    assert(error instanceof ProfileError, `${code} must use ProfileError`);
    equal((error as any).code, code, 'profile error code');
    return;
  }
  throw new Error(`expected ${code}`);
}

const badge = [1, 2, 255];
const input: any = { id: 'a', name: 'Alpha', badge };
const registry: any = new ProfileRegistry([input, { id: 'b', name: 'Beta', badge: null }]);
input.name = 'mutated';
badge[0] = 99;
equal(registry.get('a').name, 'Alpha', 'constructor does not retain profile input');
equal(registry.get('a').badge[0], 1, 'constructor copies badge input');
equal(registry.list().map((p: any) => p.id).join(','), 'a,b', 'constructor order is preserved');

const fetched = registry.get('a');
fetched.name = 'changed';
fetched.badge[1] = 88;
equal(registry.get('a').name, 'Alpha', 'get returns a fresh profile');
equal(registry.get('a').badge[1], 2, 'get returns a fresh badge');

const renamed = registry.rename('a', '  Renamed  ');
equal(renamed.name, 'Renamed', 'rename trims name');
equal(registry.get('b').name, 'Beta', 'rename updates only target');
expectCode('INVALID_NAME', () => registry.rename('a', '   '));
equal(registry.get('a').name, 'Renamed', 'failed rename leaves state unchanged');

const newBadge = [0, 128, 255];
const badged = registry.setBadge('a', newBadge);
equal(badged.badge.join(','), '0,128,255', 'setBadge replaces bytes');
newBadge[0] = 77;
badged.badge[1] = 77;
equal(registry.get('a').badge.join(','), '0,128,255', 'setBadge input and result are not aliased');

equal(registry.setBadge('a', []).badge.length, 0, 'empty badge is valid');
equal(registry.clearBadge('a').badge, null, 'clearBadge stores null');

for (const invalid of [[-1], [256], [1.5], [Number.NaN], [Infinity]]) {
  registry.setBadge('a', [7]);
  expectCode('INVALID_BADGE', () => registry.setBadge('a', invalid));
  equal(registry.get('a').badge.join(','), '7', 'invalid badge leaves state unchanged');
}

for (const operation of [
  () => registry.get('missing'),
  () => registry.rename('missing', ''),
  () => registry.setBadge('missing', [999]),
  () => registry.clearBadge('missing'),
]) expectCode('MISSING', operation);

const listed = registry.list();
listed.reverse();
listed[0].name = 'changed';
if (listed[0].badge) listed[0].badge.push(44);
equal(registry.list().map((p: any) => p.id).join(','), 'a,b', 'list array is fresh');
equal(registry.get('b').name, 'Beta', 'list profiles are fresh');

expectCode('DUPLICATE', () => new ProfileRegistry([
  { id: 'x', name: 'One', badge: null },
  { id: 'x', name: 'Two', badge: null },
]));
equal(new ProfileRegistry([]).list().length, 0, 'empty registry is valid');

